const body = $json.body ?? $json;
const headers = $json.headers ?? {};

const githubEvent =
  headers['x-github-event'] ??
  headers['X-GitHub-Event'] ??
  'unknown';

const deliveryId =
  headers['x-github-delivery'] ??
  headers['X-GitHub-Delivery'] ??
  null;

const repository = body.repository ?? {};
const sender = body.sender ?? {};

const issue = body.issue ?? null;
const pullRequest = body.pull_request ?? null;
const review = body.review ?? null;
const comment = body.comment ?? null;
const release = body.release ?? null;

const normalized = {
  github_event: githubEvent,
  action: body.action ?? null,
  delivery_id: deliveryId,

  repository: {
    id: repository.id ?? null,
    name: repository.name ?? null,
    full_name: repository.full_name ?? null,
    private: repository.private ?? null,
    url: repository.html_url ?? null
  },

  sender: {
    id: sender.id ?? null,
    login: sender.login ?? null
  },

  issue: issue
    ? {
        number: issue.number ?? null,
        title: issue.title ?? null,
        state: issue.state ?? null,
        url: issue.html_url ?? null,
        author: issue.user?.login ?? null
      }
    : null,

  pull_request: pullRequest
    ? {
        number: pullRequest.number ?? null,
        title: pullRequest.title ?? null,
        state: pullRequest.state ?? null,
        merged: pullRequest.merged ?? false,
        url: pullRequest.html_url ?? null,
        author: pullRequest.user?.login ?? null
      }
    : null,

  review: review
    ? {
        id: review.id ?? null,
        state: review.state ?? null,
        author: review.user?.login ?? null
      }
    : null,

  comment: comment
    ? {
        id: comment.id ?? null,
        body: comment.body ?? null,
        author: comment.user?.login ?? null,
        url: comment.html_url ?? null
      }
    : null,

  release: release
    ? {
        id: release.id ?? null,
        tag_name: release.tag_name ?? null,
        name: release.name ?? null,
        url: release.html_url ?? null
      }
    : null,

  received_at: new Date().toISOString()
};

return [
  {
    json: normalized
  }
];

const event = $('Normalize GitHub Event').item.json;

return [
  {
    json: {
      ...event,
      is_new: true
    }
  }
];

const aiResponse = $json.text;

const originalData = $('Prepare AI Output').item.json;

const event = originalData.ai_input;

let parsed;
const errors = [];

try {
  parsed = JSON.parse(aiResponse);
} catch (error) {
  return {
    json: {
      validation_status: "failed",
      validation_passed: false,
      errors: ["AI output is not valid JSON"],
      ai_output_raw: aiResponse,
      source_event: event,
      human_review_required: true
    }
  };
}

const allowedPriorities = [
  "high",
  "medium",
  "low",
  "informational"
];

const allowedCategories = [
  "pull_request",
  "issue",
  "review",
  "comment",
  "release",
  "push",
  "other"
];

if (!allowedPriorities.includes(parsed.priority)) {
  errors.push("Invalid priority");
}

if (typeof parsed.action_required !== "boolean") {
  errors.push("action_required must be a boolean");
}

if (!allowedCategories.includes(parsed.category)) {
  errors.push("Invalid category");
}

if (typeof parsed.summary !== "string" || !parsed.summary.trim()) {
  errors.push("summary must be a non-empty string");
}

if (typeof parsed.reason !== "string" || !parsed.reason.trim()) {
  errors.push("reason must be a non-empty string");
}

if (typeof parsed.notification !== "boolean") {
  errors.push("notification must be a boolean");
}

// Deterministic consistency checks against the GitHub event.
if (event.github_event === "issue_comment") {
  if (parsed.category !== "comment") {
    errors.push("Category contradicts the GitHub event type");
  }

  if (
    event.action === "deleted" &&
    !/delet(ed|ion)|remov(ed|al)/i.test(parsed.summary)
  ) {
    errors.push("Summary does not reflect the deleted comment event");
  }
}

// Informational events should not trigger immediate notifications.


return {
  json: {
    validation_status: errors.length === 0 ? "passed" : "failed",
    validation_passed: errors.length === 0,
    errors,
    ai_output: parsed,
    source_event: event,
    human_review_required: true
  }
};

const event = $json;

const aiInput = {
  delivery_id: event.delivery_id ?? null,
  github_event: event.github_event,
  action: event.action,

  repository: {
    full_name: event.repository?.full_name ?? null
  },

  sender: {
    login: event.sender?.login ?? null
  },

  issue: event.issue
    ? {
        number: event.issue.number,
        title: event.issue.title,
        state: event.issue.state,
        author: event.issue.author,
        url: event.issue.url
      }
    : null,

  pull_request: event.pull_request
    ? {
        number: event.pull_request.number,
        title: event.pull_request.title,
        state: event.pull_request.state,
        merged: event.pull_request.merged,
        author: event.pull_request.author,
        url: event.pull_request.url
      }
    : null,

  review: event.review
    ? {
        id: event.review.id,
        state: event.review.state,
        author: event.review.author
      }
    : null,

  comment: event.comment
    ? {
        id: event.comment.id,
        body: event.comment.body,
        author: event.comment.author,
        url: event.comment.url
      }
    : null,

  release: event.release
    ? {
        id: event.release.id,
        tag_name: event.release.tag_name,
        name: event.release.name,
        url: event.release.url
      }
    : null
};

return [
  {
    json: {
      ai_input: aiInput,
      source: "github",
      source_of_truth: "github_payload"
    }
  }
];

const result = $json;

return {
  json: {
    logged_at: new Date().toISOString(),
    status: "rejected",
    validation_status: result.validation_status,
    errors: result.errors ?? [],
    repository: result.source_event?.repository?.full_name ?? null,
    event_type: result.source_event?.github_event ?? null,
    action: result.source_event?.action ?? null,
    delivery_id: result.source_event?.delivery_id ?? null,
    ai_output: result.ai_output ?? null,
    human_review_required: true
  }
};

