const result = $json;

if (result.validation_passed !== true) {
  throw new Error("Blocked: AI output has not passed validation.");
}

const event = result.source_event;
const ai = result.ai_output;

if (!event || !ai) {
  throw new Error("Missing validated event or AI output.");
}

return {
  json: {
    delivery_id: event.delivery_id,
    repository: event.repository?.full_name ?? null,
    event_type: event.github_event,
    action: event.action,
    priority: ai.priority,
    action_required: ai.action_required,
    category: ai.category,
    summary: ai.summary,
    reason: ai.reason,
    notification: ai.notification,
    human_review_required: true,
    source_url:
      event.issue?.url ??
      event.pull_request?.url ??
      event.comment?.url ??
      event.repository?.url ??
      null
  }
};

// Pull data directly from the node that formatted it perfectly
const validatedEvent = $node["Prepare Validated Event"].json;

return [{
  json: {
    repository: validatedEvent.repository || 'Unknown Repo',
    event_type: validatedEvent.event_type || 'Unknown Event',
    summary: validatedEvent.summary || 'No summary available',
    source_url: validatedEvent.source_url || 'https://github.com'
  }
}];
